/** Stable key for a game so its AI opinion survives re-sorts/re-filters. */
const aiGameKey = (rec) =>
  [rec?.match, rec?.country, rec?.league, rec?.date].map((v) => String(v ?? "")).join("|");

/**
 * Gemini free tier allows ~5 requests/minute for the flash model.
 * The bulk "Get AI picks (all)" run paces itself to stay under this.
 * Raise this if you enable billing (paid limits are far higher).
 */
const AI_MAX_RPM = 5;

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/** Team record table: match column %; remaining % split evenly across Overall + each type column. */
const TEAM_RECORD_MATCH_COL_PCT = 24;
const TEAM_RECORD_DATA_COL_COUNT = 1 + TEAM_RECORD_COLUMNS.length;
const TEAM_RECORD_EACH_DATA_COL_PCT =
  (100 - TEAM_RECORD_MATCH_COL_PCT) / TEAM_RECORD_DATA_COL_COUNT;

const CALIBRATION_BUCKETS = [
  { id: "low", label: "0–69", min: 0, max: 69.999 },
  { id: "mid", label: "70–84", min: 70, max: 84.999 },
  { id: "high", label: "85–100", min: 85, max: 100 },
];

function getCalibrationBucketId(confidence) {
  const c = Number(confidence);
  if (!Number.isFinite(c)) return null;
  const clamped = Math.max(0, Math.min(100, c));
  const b = CALIBRATION_BUCKETS.find((x) => clamped >= x.min && clamped <= x.max);
  return b?.id ?? null;
}

function inferPrimaryTypeFromRecommendationText(recText) {
  const s = String(recText ?? "").toLowerCase();
  if (!s) return null;
  if (s.includes("over") || s.includes("under")) return "Over/Under";
  if (s.includes(" or draw") || s.includes("draw") || s.includes("double chance")) return "Double Chance";
  // Otherwise treat as straight win-style (team to win)
  return "Straight Win";
}

/** Normalize for dedupe keys (fixture + recommendation text). */
function normKeyPart(v) {
  return String(v ?? "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, " ");
}

/** Parse DB timestamps for “latest saved wins” tie-breaking. */
function rowSavedAtMs(r) {
  const candidates = [r?.created_at, r?.updated_at, r?.result_updated_at, r?.date];
  for (const c of candidates) {
    if (!c) continue;
    const t = new Date(c).getTime();
    if (!Number.isNaN(t)) return t;
  }
  return 0;
}

/**
 * When the same fixture appears on multiple slips (different BET_ID), calibration should not double-count.
 * Tie-break: latest saved row wins (created_at / updated_at).
 */
function dedupeCalibrationTierEvents(rows) {
  const bestByKey = new Map();

  for (const r of rows || []) {
    if (!r?.actual_result || String(r.actual_result).trim() === "") continue;

    const fixtureKey = [
      normKeyPart(r?.country),
      normKeyPart(r?.league),
      normKeyPart(r?.home_team),
      normKeyPart(r?.away_team),
      normKeyPart(r?.date),
    ].join("|");

    const tiers = [
      {
        tier: "primary",
        rec: r.primary_recommendation ?? r.recommendation,
        conf: r.primary_confidence ?? r.confidence_score,
        ok: r.system_primary_correct,
      },
      {
        tier: "secondary",
        rec: r.secondary_recommendation,
        conf: r.secondary_confidence,
        ok: r.system_secondary_correct,
      },
      {
        tier: "tertiary",
        rec: r.tertiary_recommendation,
        conf: r.tertiary_confidence,
        ok: r.system_tertiary_correct,
      },
    ];

    const ts = rowSavedAtMs(r);

    for (const t of tiers) {
      if (t.rec == null || String(t.rec).trim() === "") continue;
      if (typeof t.ok !== "boolean") continue;

      const rawType = inferPrimaryTypeFromRecommendationText(t.rec);
      if (!rawType) continue;

      const bucketId = getCalibrationBucketId(Number(t.conf));
      if (!bucketId) continue;

      const pickKey = normKeyPart(t.rec);
      const dedupeKey = `${t.tier}|${rawType}|${bucketId}|${fixtureKey}|${pickKey}`;

      const prev = bestByKey.get(dedupeKey);
      if (!prev || ts >= prev.ts) {
        bestByKey.set(dedupeKey, {
          tier: t.tier,
          rawType,
          bucketId,
          ok: t.ok,
          ts,
        });
      }
    }
  }

  return Array.from(bestByKey.values());
}

// Helper: is a single card (bestBet, primary, secondary, tertiary) ticket-ready?
const isCardTicketReady = (card) => {
  if (!card?.recommendation) return false;
  const conf = parseFloat(card.recommendation.confidence);
  if (isNaN(conf)) return false;
  if (card.recommendation.bet === "AVOID") return false;
  if (card.oddsPerformance?.type === "warning") return false;
  if (card.oddsTrapWarning?.isTrap) return false;

  // Exception: Straight Win with very high confidence (≥85%) and no red odds counts as ticket-ready even if risk is High
  if (card.type === "Straight Win" && conf >= 85) return true;

  // Standard rules: confidence ≥70%, risk ≠ High
  if (conf < 70) return false;
  if ((card.riskLevel || "").toLowerCase() === "high") return false;
  return true;
};

// Helper: does this rec have at least one ticket-ready card?
const hasAnyTicketReady = (rec) =>
  (rec.bestBet && isCardTicketReady(rec.bestBet)) ||
  (rec.primary && isCardTicketReady(rec.primary)) ||
  (rec.secondary && isCardTicketReady(rec.secondary)) ||
  (rec.tertiary && isCardTicketReady(rec.tertiary));

const HIGH_SCORING_THRESHOLD = 2; // 2 or higher

/** Highlight class for Team record cells that tie for best win % */
const TEAM_RECORD_BEST_CELL =
  "bg-emerald-500/25 ring-1 ring-emerald-400/60 rounded-md shadow-[inset_0_1px_0_0_rgba(255,255,255,0.06)]";

function getTeamRecordBestHighlights(stats) {
  if (!stats) {
    return { maxPct: null, bestTypeKeys: new Set() };
  }
  const items = [];
  for (const row of stats.byType || []) {
    if (row?.pct != null && row.total > 0) {
      items.push({ type: row.type, pct: Number(row.pct) });
    }
  }
  if (items.length === 0) {
    return { maxPct: null, bestTypeKeys: new Set() };
  }
  const maxPct = Math.max(...items.map((i) => i.pct));
  const atMax = (p) => Math.abs(p - maxPct) < 0.04;
  const bestTypeKeys = new Set(
    items.filter((i) => atMax(i.pct)).map((i) => i.type),
  );
  return { maxPct, bestTypeKeys };
}

function formatTeamRecordBestSummary(stats, headerLabel) {
  const { maxPct, bestTypeKeys } = getTeamRecordBestHighlights(stats);
  if (maxPct == null || bestTypeKeys.size === 0) return null;
  const names = [];
  for (const col of TEAM_RECORD_COLUMNS) {
    if (bestTypeKeys.has(col)) names.push(headerLabel(col));
  }
  if (names.length === 0) return null;
  const pctLabel = Number.isInteger(maxPct) ? String(maxPct) : maxPct.toFixed(1);
  return `${pctLabel}% — ${names.join(" · ")}`;
}

