  // AI second opinions, keyed by game so results persist across sort/filter.
  const [aiOpinions, setAiOpinions] = useState({}); // key -> { data } | { error }
  const [aiLoadingKeys, setAiLoadingKeys] = useState({}); // key -> true
  const [aiBulkLoading, setAiBulkLoading] = useState(false);
  const [aiProgress, setAiProgress] = useState({ done: 0, total: 0 });
  /** Which recommendation cards show secondary/tertiary + extra detail. */
  const [expandedRecKeys, setExpandedRecKeys] = useState({});

  const fetchAiForRec = useCallback(async (rec) => {
    const key = aiGameKey(rec);
    setAiLoadingKeys((prev) => ({ ...prev, [key]: true }));
    try {
      const data = await getAiSecondOpinion(rec);
      setAiOpinions((prev) => ({ ...prev, [key]: { data } }));
      // Best-effort persist for scoreboard (needs prior "Save betslip" so rows exist)
      saveAiOpinionToDb(rec, data).catch(() => {});
    } catch (e) {
      setAiOpinions((prev) => ({ ...prev, [key]: { error: e.message || "Failed to get AI opinion" } }));
    } finally {
      setAiLoadingKeys((prev) => {
        const next = { ...prev };
        delete next[key];
        return next;
      });
    }
  }, []);

  // Fetch AI opinions for every visible game, paced to the free-tier rate limit.
  const fetchAllAi = useCallback(
    async (games) => {
      if (!games || games.length === 0) return;
      setAiBulkLoading(true);
      setAiProgress({ done: 0, total: games.length, waiting: false });

      const starts = []; // timestamps of recent request starts (sliding 60s window)
      const acquireSlot = async () => {
        for (;;) {
          const now = Date.now();
          while (starts.length && now - starts[0] >= 60000) starts.shift();
          if (starts.length < AI_MAX_RPM) {
            starts.push(now);
            setAiProgress((p) => ({ ...p, waiting: false }));
            return;
          }
          const waitMs = 60000 - (now - starts[0]) + 300;
          setAiProgress((p) => ({ ...p, waiting: true }));
          await sleep(waitMs);
        }
      };

      const total = games.length;
      let done = 0;
      for (const game of games) {
        await acquireSlot();
        await fetchAiForRec(game);
        done += 1;
        const completed = done;
        setAiProgress((p) => ({ ...p, done: completed, total }));
      }
      setAiBulkLoading(false);
    },
    [fetchAiForRec]
  );

  useEffect(() => {
    let cancelled = false;
    getSofascoreStatus()
      .then((s) => {
        if (!cancelled) setSofaStatus(s);
      })
      .catch(() => {
        if (!cancelled) setSofaStatus({ ready: false, enabled: false });
      });
    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    let cancelled = false;
    async function loadCalibration() {
      setCalibrationLoading(true);
      try {
        const res = await fetch("/api/betslip-recommendations");
        if (!res.ok) throw new Error(`Calibration fetch failed: ${res.status}`);
        const rows = await res.json();
        const dedupedEvents = dedupeCalibrationTierEvents(rows);

        // Build: tier -> type -> bucketId -> { n, correct }
        const acc = {};
        const ensure = (tier, type, bucketId) => {
          if (!acc[tier]) acc[tier] = {};
          if (!acc[tier][type]) acc[tier][type] = {};
          if (!acc[tier][type][bucketId]) acc[tier][type][bucketId] = { n: 0, correct: 0 };
          return acc[tier][type][bucketId];
        };

        dedupedEvents.forEach((ev) => {
          const slot = ensure(ev.tier, ev.rawType, ev.bucketId);
          slot.n += 1;
          if (ev.ok) slot.correct += 1;
        });

        if (!cancelled) setCalibrationByTier(acc);
      } catch (e) {
        if (!cancelled) setCalibrationByTier(null);
        // Keep UI silent; calibration is optional.
        // eslint-disable-next-line no-console
        console.warn(e);
      } finally {
        if (!cancelled) setCalibrationLoading(false);
      }
    }

    loadCalibration();
    return () => {
      cancelled = true;
    };
  }, []);

  const renderCalibratedLine = (tier, card) => {
    if (!card?.recommendation || card.recommendation.bet === "AVOID") return null;
    const rawConf = Number(card.recommendation.confidence);
    const bucketId = getCalibrationBucketId(rawConf);
    const type = card.type;
    const slot = bucketId && calibrationByTier?.[tier]?.[type]?.[bucketId];
    const bucketLabel =
      CALIBRATION_BUCKETS.find((b) => b.id === bucketId)?.label ?? bucketId;

    if (!slot || !slot.n) {
      return (
        <div className="text-gray-400 text-xs mt-1">
          Calibrated: —{" "}
          <span className="text-gray-500">
            {calibrationLoading ? "(loading…)" : "(no data yet)"}
          </span>
        </div>
      );
    }

    const pct = (slot.correct / slot.n) * 100;
    return (
      <div className="text-gray-400 text-xs mt-1">
        Calibrated:{" "}
        <span className="text-white font-medium">{pct.toFixed(0)}%</span>{" "}
        <span className="text-gray-500">
          (raw {bucketLabel}, N={slot.n})
        </span>
      </div>
    );
  };

